// `@types/node`'s `events.d.ts` shape. A module `export =`s a class that is
// MERGED with a namespace, and the namespace publishes the class under its own
// name through an ALIAS — `export { internal as EventEmitter }`, where
// `internal` is `import internal = require("node:events")` pointing back at the
// module itself.
//
// A namespace's `export { … }` is not an export of the module around it, so it
// is not in the module's export table; but it IS a member of the namespace, and
// `import { EventEmitter } from "events"` reads exactly that member through the
// `export =`. Dropping the record entirely made the import `any`.
declare module "evts" {
  class EE {
    on(k: string, listener: (...args: any[]) => void): this;
    count: number;
  }
  import internal = require("evts-alias");
  namespace EE {
    export { internal as EE };
    export interface Options {
      capture: boolean;
    }
  }
  export = EE;
}

declare module "evts-alias" {
  import evts = require("evts");
  export = evts;
}

// The same alias with no module cycle in it: the namespace re-exports a plain
// LOCAL under a different name.
declare module "evts2" {
  class E2 {
    tag(): string;
  }
  class Inner {
    m(): number;
  }
  namespace E2 {
    export { Inner as Renamed };
  }
  export = E2;
}
